const date = (value) => value === null ? null : new Date(value);

export async function seedLegalTemplates(prisma) {
  for (const template of legalTemplateCatalog) {
    const { appCode, role, kind, locale, version, ...fields } = template;
    const identity = { appCode, role, kind, locale, version };
    const data = { ...fields, deletedAt: date(fields.deletedAt),
      createdAt: date(fields.createdAt), updatedAt: date(fields.updatedAt) };
    await prisma.appLegalTemplate.upsert({
      where: { appCode_role_kind_locale_version: identity },
      create: { ...identity, ...data }, update: data,
    });
  }
}

export async function seedLegal(prisma) {
  for (const document of legalDocumentCatalog) {
    const { clientCode, appCode, role, kind, locale, version, ...fields } = document;
    if (createHash('sha256').update(fields.content, 'utf8').digest('hex') !== fields.contentHash)
      throw new Error(`Legal seed hash mismatch: ${clientCode}/${appCode}/${kind}/${locale}/${version}`);
    const client = clientCode === null ? null : await prisma.client.findFirst({
      where: { OR: [{ companyCode: clientCode }, { slug: clientCode }] }, select: { id: true },
    });
    if (clientCode !== null && !client)
      throw new Error(`Client ${clientCode} is absent. Seed clients before legal documents.`);
    const identity = { clientId: client?.id ?? null, appCode, role, kind, locale, version };
    const existing = await prisma.appLegalDocument.findFirst({ where: identity });
    if (existing?.publishedAt) {
      if (existing.contentHash !== fields.contentHash)
        throw new Error(`Published legal document differs from seed: ${clientCode}/${appCode}/${kind}/${locale}/${version}`);
      continue;
    }
    const data = { ...fields, effectiveAt: date(fields.effectiveAt),
      publishedAt: date(fields.publishedAt), retiredAt: date(fields.retiredAt),
      deletedAt: date(fields.deletedAt), createdAt: date(fields.createdAt) };
    if (existing) await prisma.appLegalDocument.update({ where: { id: existing.id }, data });
    else await prisma.appLegalDocument.create({ data: { ...identity, ...data } });
  }
}
